// DirectDraw-surface texture (.dds) resource, a CRes subclass that exposes a typed header view
// plus a byte-copy of the pixel data.

#ifndef CRESDDS_H
#define CRESDDS_H

#include "exoresman.h"

// The DDS header at the front of the file buffer. The first four dwords are byte-swapped on load.
struct DDSHeader {
    unsigned int m_width;
    unsigned int m_height;
    unsigned int m_nBytesPerPixel;
    unsigned int m_nDataSize;
    unsigned int m_fAlphaTest;
};

class CResDDS : public CRes {
public:
    CResDDS();
    // <VTABLE-GEN: binary ground truth (_ZTV) — regenerated by tools/hoist_headers.py; do not edit inside markers */
    //   primary vtable, 6 slots
    virtual ~CResDDS();  // slots 0-1 (D2+D0)
    virtual int OnResourceFreed();
    virtual int OnResourceServiced();
    // </VTABLE-GEN>

    int   CopyDDSData(unsigned char* pDst);
    int   GetDDSAttrib(unsigned int* pWidth, unsigned int* pHeight,
                       unsigned char* pBytesPerPixel, unsigned int* pDataSize, float* pAlphaTest);
    void* GetDDSDataPtr();
    void* GetDDSHeaderPtr();
    int   GetDDSSize();
    int   IsLoaded();

    int          m_bLoaded;
    unsigned int m_nDDSSize;
    void* m_pDDSData;
    void* m_pDDSHeader;
};

#endif
